import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int r = sc.nextInt();
        int[][] table = new int[r][];

        for (int i = 0; i < r; i++) {
            int k = sc.nextInt();
            table[i] = new int[k];
            for (int j = 0; j < k; j++) {
                table[i][j] = sc.nextInt();
            }
        }

        int total = 0;
        for (int i = 0; i < table.length; i++) {
            int rowSum = 0;
            for (int j = 0; j < table[i].length; j++) {
                rowSum += table[i][j];
            }
            System.out.println("行" + (i + 1) + " " + rowSum);
            total += rowSum;
        }
        System.out.println("合計 " + total);
    }
}

